        // Check balances after call
        uint256 tokenBalanceAfter = flakyToken.balanceOf(address(token));
        uint256 ownerBalanceAfter = flakyToken.balanceOf(owner);

        // Verify tokens remain in contract after failed transfer
        assertEq(tokenBalanceAfter, tokenBalanceBefore, "Token balance should remain unchanged");
        assertEq(ownerBalanceAfter, ownerBalanceBefore, "Owner should not receive tokens");
    }
}
